  ('Restaurant Orders', 'Kitchen tickets with service type and rating', '["summaries","avgByGroup","distribution","stacked","activity","weekday","topValues"]'),
  ('Clinic Visits', 'Outpatient appointments and wait times', '["summaries","avgByGroup","distribution","activity","booleanRatio"]'),
  ('Fleet Fuel Logs', 'Vehicle refueling and odometer records', '["summaries","avgByGroup","scatter","distribution","activity","booleanRatio"]'),
  ('Real Estate Listings', 'Property inventory with pricing and status', '["summaries","avgByGroup","scatter","distribution","activity","topValues"]'),
  ('Event Tickets', 'Ticket sales by tier and sales channel', '["summaries","avgByGroup","distribution","stacked","activity","booleanRatio"]'),
  ('Support Tickets', 'Customer support cases and resolution metrics', '["summaries","avgByGroup","distribution","activity","weekday","booleanRatio"]'),
  ('Library Loans', 'Book lending activity and returns', '["summaries","avgByGroup","distribution","activity","booleanRatio","topValues"]'),
  ('Weather Readings', 'Environmental sensor measurements by station', '["summaries","avgByGroup","scatter","distribution","activity","trend"]');
